pub mod generated {
    //! Generated constants — regenerated by `cargo xtask codegen`, never edited by hand.
    pub mod subtypes;

    #[cfg(test)]
    mod subtype_tests {
        use super::subtypes;

        /// `NAMES` is a dense array indexed by subtype id. If codegen ever
        /// emitted the constants and the name table out of step, every type
        /// line a client builds would be silently wrong — off by one, with
        /// plausible-looking output. Length and round trip are what catch it.
        #[test]
        fn every_subtype_id_has_a_name_that_maps_back_to_it() {
            assert_eq!(subtypes::NAMES.len(), subtypes::COUNT as usize);
            for id in 0..subtypes::COUNT {
                let id = crate::ids::SubtypeId::new(id);
                let name = subtypes::name(id).expect("every id in range is named");
                assert_eq!(
                    subtypes::by_name(name),
                    Some(id),
                    "{name} does not map back to its own id"
                );
            }
        }

        /// The names are the printed spelling, not the constant spelling —
        /// a type line says `Assembly-Worker`, never `ASSEMBLY_WORKER`.
        #[test]
        fn names_are_printed_spelling() {
            assert_eq!(
                subtypes::name(subtypes::creature::ASSEMBLY_WORKER),
                Some("Assembly-Worker")
            );
            assert_eq!(subtypes::name(subtypes::land::FOREST), Some("Forest"));
        }
    }
}
