/// Parses a mana cost literal **at compile time**; invalid literals are
/// compile errors. See `docs/mana-notation.md`.
///
/// ```
/// let cost = baylee_core::mana!("{2}{W/U}{W/P}");
/// assert_eq!(cost.cmc(), 4);
/// ```
///
/// ```compile_fail
/// let _ = baylee_core::mana!("not a cost");
/// ```
#[macro_export]
macro_rules! mana {
    ($s:literal) => {{
        const COST: $crate::mana::ManaCost = $crate::mana::ManaCost::parse($s);
        COST
    }};
}
